//		Exec(ctx)
func (_c *ExamCreateBulk) OnConflictColumns(columns ...string) *ExamUpsertBulk {
	_c.conflict = append(_c.conflict, sql.ConflictColumns(columns...))
	return &ExamUpsertBulk{
		create: _c,
	}
}

